use circuit_breaker::{CircuitBreaker, CircuitError};

fn boom() -> Result<String, String> {
    Err("boom".to_string())
}

#[test]
fn trips_open_after_consecutive_failures() {
    let mut b = CircuitBreaker::new(3, 10);
    for _ in 0..3 {
        assert_eq!(b.call(boom, 0), Err(CircuitError::Inner("boom".to_string())));
    }
    assert_eq!(b.call(|| Ok("should not run".to_string()), 0), Err(CircuitError::Open));
}

#[test]
fn fails_fast_without_calling_fn_while_open() {
    let mut b = CircuitBreaker::new(1, 100);
    let _ = b.call(boom, 0);
    let mut called = false;
    let result = b.call(|| { called = true; Ok("x".to_string()) }, 1);
    assert_eq!(result, Err(CircuitError::Open));
    assert!(!called);
}

#[test]
fn half_open_trial_after_timeout_success_closes() {
    let mut b = CircuitBreaker::new(1, 10);
    let _ = b.call(boom, 0);
    assert_eq!(b.call(|| Ok("ok".to_string()), 10), Ok("ok".to_string()));
    assert_eq!(b.call(|| Ok("still-fine".to_string()), 11), Ok("still-fine".to_string()));
}

#[test]
fn half_open_failure_reopens_and_resets_clock() {
    let mut b = CircuitBreaker::new(1, 10);
    let _ = b.call(boom, 0);
    assert_eq!(b.call(boom, 10), Err(CircuitError::Inner("boom".to_string())));
    assert_eq!(b.call(|| Ok("too soon".to_string()), 15), Err(CircuitError::Open));
    assert_eq!(b.call(|| Ok("ok now".to_string()), 20), Ok("ok now".to_string()));
}

